// ── Resolve Decisions ────────────────────────────────────────────────────
// Processes actionable flags from the Awaiting Decision section.
// Actionable = checked [x] AND has a decision annotation.
//
// Supported decision types:
//   "project: <slug>"  → setFrontmatter { key: 'project', value: slug }
//   "type: <type>"     → setFrontmatter { key: 'type', value: type }
//   "area: <area>"     → setFrontmatter { key: 'area', value: area }
//   "skip" / "ignore" → remove flag, no file edit
//   anything else      → unrecognised, leave flag in place
// ─────────────────────────────────────────────────────────────────────────

const input = $input.item.json;
const controlFileContent = input.controlFileContent ?? '';
const awaitingFlags      = Array.isArray(input.awaitingFlags) ? input.awaitingFlags : [];
const controlFilePath    = input.controlFilePath ?? '';

const actioned      = [];
const unrecognised  = [];
const skipped       = [];
const toRemovePaths = new Set(); // filePaths whose flag lines should be stripped

for (const flag of awaitingFlags) {
  if (!flag.readyToAction) continue;

  const decision = (flag.decision ?? '').trim().toLowerCase();

  if (decision === 'skip' || decision === 'ignore') {
    skipped.push({ filePath: flag.filePath, description: flag.description });
    toRemovePaths.add(flag.filePath);
    continue;
  }

  const fmMatch = decision.match(/^(project|type|area):\s*(.+)$/);
  if (fmMatch) {
    const key   = fmMatch[1];
    const value = fmMatch[2].trim();
    actioned.push({
      filePath:    flag.filePath,
      description: flag.description,
      decision:    flag.decision,
      action:      { type: 'setFrontmatter', key, value }
    });
    toRemovePaths.add(flag.filePath);
    continue;
  }

  // Unrecognised — leave flag in place
  unrecognised.push({ filePath: flag.filePath, decision: flag.decision });
}

// ── Strip resolved flags from control file ────────────────────────────────
let updatedControlContent = controlFileContent;

if (toRemovePaths.size > 0) {
  const lines = controlFileContent.split('\n');
  const out   = [];
  let skip    = false;

  for (const line of lines) {
    // Flag line format: "- [x] `path/to/file.md` — description"
    const flagLineMatch = line.match(/^- \[[ x]\] `([^`]+)`/);
    if (flagLineMatch) {
      const linePath = flagLineMatch[1];
      if (toRemovePaths.has(linePath)) {
        skip = true; // skip this line and any immediately following indented lines
        continue;
      } else {
        skip = false;
      }
    } else if (skip && (line.startsWith('  ') || line.trim() === '')) {
      // Indented continuation or blank line after a removed flag — skip
      continue;
    } else {
      skip = false;
    }
    out.push(line);
  }
  updatedControlContent = out.join('\n');
}

// ── Build edit payload for file frontmatter updates ───────────────────────
const editPayload = actioned
  .filter(a => a.action?.type === 'setFrontmatter')
  .map(a => ({ filePath: a.filePath, key: a.action.key, value: a.action.value }));

const hasChanges = actioned.length > 0 || skipped.length > 0;

console.log(`Resolve Decisions: ${actioned.length} actioned, ${skipped.length} skipped, ${unrecognised.length} unrecognised`);

return [{ json: {
  actioned,
  unrecognised,
  skipped,
  editPayload,
  updatedControlContent,
  controlFilePath,
  hasChanges,
  obsidianBaseUrl: input.obsidianBaseUrl
}}];

// Prepare edit payload — actual HTTP calls to Obsidian REST API for each frontmatter fix
// editPayload items: { filePath, key, value }
const data        = $input.item.json;
const editPayload = data.editPayload ?? [];
const baseUrl     = data.obsidianBaseUrl ?? '';
const results     = [];

for (const edit of editPayload) {
  try {
    // Read the file
    const readRes = await $helpers.httpRequest({
      method: 'GET',
      url: `${baseUrl}/vault/${edit.filePath.split('/').map(encodeURIComponent).join('/')}`,
      headers: { Accept: 'text/markdown' },
      skipSslCertificateValidation: true,
      returnFullResponse: true
    });
    const originalContent = readRes.body ?? '';

    // Set/replace the frontmatter key
    const fmMatch = originalContent.match(/^(---\n[\s\S]*?\n---\n)/);
    if (!fmMatch) {
      results.push({ filePath: edit.filePath, key: edit.key, value: edit.value, status: 'error', error: 'No frontmatter block found' });
      continue;
    }
    const fmBlock = fmMatch[1];
    const rest    = originalContent.slice(fmBlock.length);
    let newFm;
    const keyLineRe = new RegExp(`^${edit.key}:.*$`, 'm');
    if (keyLineRe.test(fmBlock)) {
      newFm = fmBlock.replace(keyLineRe, `${edit.key}: ${edit.value}`);
    } else {
      // Insert before closing ---
      newFm = fmBlock.replace(/\n---\n$/, `\n${edit.key}: ${edit.value}\n---\n`);
    }
    const newContent = newFm + rest;

    // Write back
    await $helpers.httpRequest({
      method: 'PUT',
      url: `${baseUrl}/vault/${edit.filePath.split('/').map(encodeURIComponent).join('/')}`,
      headers: { 'Content-Type': 'text/markdown' },
      body: newContent,
      skipSslCertificateValidation: true
    });
    results.push({ filePath: edit.filePath, key: edit.key, value: edit.value, status: 'written' });
  } catch (err) {
    results.push({ filePath: edit.filePath, key: edit.key, value: edit.value, status: 'error', error: err.message });
  }
}

console.log(`Apply File Edits: ${results.filter(r => r.status === 'written').length} written, ${results.filter(r => r.status === 'error').length} errors`);

return [{ json: { ...data, fileEditResults: results } }];
